import { type ReactNode } from "react";
import * as Accordion from "@radix-ui/react-accordion";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/cn";

// KMP-C24 (specs/KMP-C24-day-accordion.md). Radix Accordion, single and collapsible, restyled.
// Not supported: nesting an accordion inside a panel; the panel holds the consumer's slot rows (KMP-C25).

export type DayAccordionItem = {
  value: string;
  /** Day label, for example "Tuesday 4 November". Shown as supplied. */
  label: string;
  /** Language of the label (for Indic or mixed text); uppercase and tracking apply to Latin text only. */
  labelLang?: string;
  /** Consumer text such as "4 slots". Part of the accessible name. */
  hint?: string;
  /** The panel content. Required: an item without content is a defect. */
  content: ReactNode;
};

export type DayAccordionProps = {
  items: DayAccordionItem[];
  /** Open item, or "" for none. Controlled when set. */
  value?: string;
  /** Uncontrolled initial value; default none open (Q-A3). */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Heading level of each header (Q-A4, provisional h2). */
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  className?: string;
};

const NAV_KEYS = new Set(["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Home", "End"]);

const item = cn(
  // The border width is reserved in every state; only its colour changes, so nothing moves on open.
  "rounded-control border-bw-heavy border-border-card bg-surface-raised",
  "data-[state=open]:border-primary-text",
  "has-[[data-day-trigger]:focus-visible]:outline has-[[data-day-trigger]:focus-visible]:outline-ring has-[[data-day-trigger]:focus-visible]:outline-offset-ring has-[[data-day-trigger]:focus-visible]:outline-focus-ring",
);

const trigger = cn(
  "group flex min-h-control w-full items-center justify-between gap-gap-md rounded-inner px-inset-md py-inset-sm text-start",
  // the ring is drawn on the whole item (has-[[data-day-trigger]:focus-visible] above), so the button itself shows none
  "font-body leading-normal text-text-muted [outline-style:none]",
  "data-[state=open]:text-primary-text",
  // shut: sunken fill on hover and press. open: never a fill (primary.text on sunken is under 7:1); underline instead.
  "data-[state=closed]:hover:bg-surface-sunken data-[state=closed]:active:bg-surface-sunken",
  "data-[state=open]:active:text-primary-active [&[data-state=open]:hover_.day-label]:underline [&[data-state=open]:active_.day-label]:underline",
);

export function DayAccordion({ items, value, defaultValue = "", onValueChange, headingLevel = 2, className }: DayAccordionProps) {
  if (items.length === 0) return null;
  const Heading = `h${headingLevel}` as const;
  const controlled = value === undefined ? { defaultValue } : { value };

  return (
    <Accordion.Root
      type="single"
      collapsible
      {...controlled}
      onValueChange={onValueChange}
      // Contract is Tab, Enter and Space only (decided; Q-A9). Radix has no switch for its arrow/Home/End
      // navigation, so stop those keys before Radix sees them. No preventDefault: the page can still scroll.
      onKeyDownCapture={(e) => {
        // only for the headers: controls inside a panel (a chip group, a listbox) keep their own key handling
        if (NAV_KEYS.has(e.key) && (e.target as HTMLElement).closest("[data-day-trigger]")) e.stopPropagation();
      }}
      className={cn("flex flex-col gap-gap-sm", className)}
    >
      {items.map((it) => (
        <Accordion.Item key={it.value} value={it.value} className={item}>
          <Accordion.Header asChild>
            <Heading>
              <Accordion.Trigger data-day-trigger="" className={trigger}>
                <span className="flex min-w-0 flex-col gap-1">
                  <span className="block">
                  <span
                    lang={it.labelLang}
                    className="day-label text-ui-floor font-semibold [overflow-wrap:anywhere] latin:uppercase latin:tracking-label"
                  >
                    {it.label}
                  </span>
                  {/* inline (not absolute, not inline-block: that adds a space before the comma) so the accessible name reads "label, hint" with no space before the comma */}
                    {it.hint && <span className="[clip-path:inset(50%)]">,</span>}
                  </span>
                  {" "}
                  {it.hint && (
                    <>
                      <span className="text-ui-floor font-regular text-text-muted">{it.hint}</span>
                    </>
                  )}
                </span>
                <ChevronDown
                  aria-hidden="true"
                  className="size-icon-lg shrink-0 transition-transform duration-base ease-standard group-data-[state=open]:rotate-180"
                />
              </Accordion.Trigger>
            </Heading>
          </Accordion.Header>
          <Accordion.Content className="overflow-hidden data-[state=closed]:animate-panel-up data-[state=open]:animate-panel-down">
            <div className="border-t-bw-default border-border-subtle p-inset-sm">{it.content}</div>
          </Accordion.Content>
        </Accordion.Item>
      ))}
    </Accordion.Root>
  );
}
